-- ARM9 BIOS ROM — GENERATED by sim/tests/hle_bios9/build.sh from
-- bios9.s, do not edit. Served at 0xFFFF0000 (NDS9 high-vector boot
-- ROM window) through nds_membus9's brom port.
--
-- Serves the retail BIOS image from sim/tests/bios9_retail.hex when that
-- file exists in the sim working directory (see make_retail_bios.sh;
-- gitignored, never committed), else the built-in HLE image below.
-- The file probe is elaboration-time textio; in synthesis the hex is
-- absent, so this reduces to the HLE constant.

library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.numeric_std.all;
use IEEE.std_logic_textio.all;
use std.textio.all;

library MEM;

entity nds_bios9 is
   generic
   (
      is_simu : std_logic := '0';
      use_cyclone5_primitive : std_logic := '0'
   );
   port
   (
      clk       : in  std_logic;
      brom_addr : in  unsigned(14 downto 2);
      brom_data : out std_logic_vector(31 downto 0);

      load_addr   : in unsigned(11 downto 2) := (others => '0');
      load_data   : in std_logic_vector(31 downto 0) := (others => '0');
      load_be     : in std_logic_vector(3 downto 0) := (others => '0');
      load_we     : in std_logic := '0';
      load_done   : in std_logic := '0'
   );
end entity;

architecture arch of nds_bios9 is

   -- 4 KB retail bios9 image; the 32 KB window reads 0 above it
   type t_rom is array (0 to 1023) of std_logic_vector(31 downto 0);

   type t_hle is array (0 to 79) of std_logic_vector(31 downto 0);
   constant HLE : t_hle := (
      x"EAFFFFFE",  -- 0x00  b	ffff0000 <vec_reset>
      x"EAFFFFFE",  -- 0x04  b	ffff0004 <vec_undef>
      x"EA00000E",  -- 0x08  b	ffff0048 <swi_handler>
      x"EAFFFFFE",  -- 0x0C  b	ffff000c <vec_pabt>
      x"EAFFFFFE",  -- 0x10  b	ffff0010 <vec_dabt>
      x"EAFFFFFE",  -- 0x14  b	ffff0014 <vec_resv>
      x"EA000000",  -- 0x18  b	ffff0020 <irq_handler>
      x"EAFFFFFE",  -- 0x1C  b	ffff001c <vec_fiq>
      x"E92D500F",  -- 0x20  push	{r0, r1, r2, r3, ip, lr}
      x"EE19CF11",  -- 0x24  mrc	15, 0, ip, cr9, cr1, {0}
      x"E1A0C62C",  -- 0x28  lsr	ip, ip, #12
      x"E1A0C60C",  -- 0x2C  lsl	ip, ip, #12
      x"E28CC901",  -- 0x30  add	ip, ip, #16384	@ 0x4000
      x"E51CC004",  -- 0x34  ldr	ip, [ip, #-4]
      x"E28FE000",  -- 0x38  add	lr, pc, #0
      x"E12FFF1C",  -- 0x3C  bx	ip
      x"E8BD500F",  -- 0x40  pop	{r0, r1, r2, r3, ip, lr}
      x"E25EF004",  -- 0x44  subs	pc, lr, #4
      x"E92D5800",  -- 0x48  push	{fp, ip, lr}
      x"E14FC000",  -- 0x4C  mrs	ip, SPSR
      x"E31C0020",  -- 0x50  tst	ip, #32
      x"155EB002",  -- 0x54  ldrbne	fp, [lr, #-2]
      x"051EB004",  -- 0x58  ldreq	fp, [lr, #-4]
      x"01A0B82B",  -- 0x5C  lsreq	fp, fp, #16
      x"E20BB0FF",  -- 0x60  and	fp, fp, #255	@ 0xff
      x"E35B0003",  -- 0x64  cmp	fp, #3
      x"0A000008",  -- 0x68  beq	ffff0090 <swi_waitbyloop>
      x"E35B0009",  -- 0x6C  cmp	fp, #9
      x"0A000009",  -- 0x70  beq	ffff009c <swi_div>
      x"E35B000E",  -- 0x74  cmp	fp, #14
      x"0A000024",  -- 0x78  beq	ffff0110 <swi_getcrc16>
      x"E35B000F",  -- 0x7C  cmp	fp, #15
      x"0A000020",  -- 0x80  beq	ffff0108 <swi_isdebugger>
      x"EAFFFFFE",  -- 0x84  b	ffff0084 <swi_bad>
      x"E8BD5800",  -- 0x88  pop	{fp, ip, lr}
      x"E1B0F00E",  -- 0x8C  movs	pc, lr
      x"E2500001",  -- 0x90  subs	r0, r0, #1
      x"CAFFFFFD",  -- 0x94  bgt	ffff0090 <swi_waitbyloop>
      x"EAFFFFFA",  -- 0x98  b	ffff0088 <swi_ret>
      x"E92D0034",  -- 0x9C  push	{r2, r4, r5}
      x"E2104102",  -- 0xA0  ands	r4, r0, #-2147483648	@ 0x80000000
      x"42600000",  -- 0xA4  rsbmi	r0, r0, #0
      x"E2115102",  -- 0xA8  ands	r5, r1, #-2147483648	@ 0x80000000
      x"42611000",  -- 0xAC  rsbmi	r1, r1, #0
      x"E3A02000",  -- 0xB0  mov	r2, #0
      x"E3A0C001",  -- 0xB4  mov	ip, #1
      x"E1510000",  -- 0xB8  cmp	r1, r0
      x"91A01081",  -- 0xBC  lslls	r1, r1, #1
      x"91A0C08C",  -- 0xC0  lslls	ip, ip, #1
      x"9AFFFFFB",  -- 0xC4  bls	ffff00b8 <swi_div+0x1c>
      x"E1B0C0AC",  -- 0xC8  lsrs	ip, ip, #1
      x"0A000004",  -- 0xCC  beq	ffff00e4 <swi_div+0x48>
      x"E1A010A1",  -- 0xD0  lsr	r1, r1, #1
      x"E1500001",  -- 0xD4  cmp	r0, r1
      x"20400001",  -- 0xD8  subcs	r0, r0, r1
      x"2082200C",  -- 0xDC  addcs	r2, r2, ip
      x"EAFFFFF8",  -- 0xE0  b	ffff00c8 <swi_div+0x2c>
      x"E1A03002",  -- 0xE4  mov	r3, r2
      x"E1340005",  -- 0xE8  teq	r4, r5
      x"42622000",  -- 0xEC  rsbmi	r2, r2, #0
      x"E1B04004",  -- 0xF0  movs	r4, r4
      x"42600000",  -- 0xF4  rsbmi	r0, r0, #0
      x"E1A01000",  -- 0xF8  mov	r1, r0
      x"E1A00002",  -- 0xFC  mov	r0, r2
      x"E8BD0034",  -- 0x100  pop	{r2, r4, r5}
      x"EAFFFFDF",  -- 0x104  b	ffff0088 <swi_ret>
      x"E3A00000",  -- 0x108  mov	r0, #0
      x"EAFFFFDD",  -- 0x10C  b	ffff0088 <swi_ret>
      x"E59FC024",  -- 0x110  ldr	ip, [pc, #36]	@ ffff013c <swi_getcrc16+0x2c>
      x"E2522001",  -- 0x114  subs	r2, r2, #1
      x"BAFFFFDA",  -- 0x118  blt	ffff0088 <swi_ret>
      x"E4D1B001",  -- 0x11C  ldrb	fp, [r1], #1
      x"E020000B",  -- 0x120  eor	r0, r0, fp
      x"E3A0B008",  -- 0x124  mov	fp, #8
      x"E1B000A0",  -- 0x128  lsrs	r0, r0, #1
      x"2020000C",  -- 0x12C  eorcs	r0, r0, ip
      x"E25BB001",  -- 0x130  subs	fp, fp, #1
      x"1AFFFFFB",  -- 0x134  bne	ffff0128 <swi_getcrc16+0x18>
      x"EAFFFFF5",  -- 0x138  b	ffff0114 <swi_getcrc16+0x4>
      x"0000A001"   -- 0x13C  .word	0x0000a001
   );

   -- Quartus 17 provides hread through IEEE.std_logic_textio. Its elaborator
   -- cannot bound-prove a file-driven while loop, so use a bounded for/exit
   -- loop for this simulation-only retail BIOS loader.
   impure function init_rom return t_rom is
      file f      : text;
      variable st : file_open_status;
      variable l  : line;
      variable w  : std_logic_vector(31 downto 0);
      variable m  : t_rom := (others => (others => '0'));
      variable i  : integer := 0;
   begin
      file_open(st, f, "sim/tests/bios9_retail.hex", read_mode);
      if (st = open_ok) then
         for k in t_rom'range loop
            exit when endfile(f);
            readline(f, l);
            hread(l, w);
            m(k) := w;
            i := i + 1;
         end loop;
         file_close(f);
         report "nds_bios9: serving RETAIL BIOS (" & integer'image(i) & " words)" severity note;
      else
         for k in t_hle'range loop
            m(k) := HLE(k);
         end loop;
         report "nds_bios9: retail hex not found, serving HLE BIOS" severity note;
      end if;
      return m;
   end function;

   signal hot_q   : std_logic_vector(31 downto 0) := (others => '0');
   signal hle_q   : std_logic_vector(31 downto 0) := HLE(0);
   signal hot_valid_q : std_logic := '1';

begin

   gsim : if is_simu = '1' generate
      constant ROM : t_rom := init_rom;
   begin
      -- Registered to match the hardware M10K and the membus accept-cycle
      -- address contract (notably exception-vector fetches).
      process (clk)
      begin
         if rising_edge(clk) then
            if to_integer(brom_addr) <= t_rom'high then
               brom_data <= ROM(to_integer(brom_addr));
            else
               brom_data <= x"00000000";
            end if;
         end if;
      end process;
   end generate;

   ghot : if is_simu = '0' generate
   begin
      ihot : entity MEM.SyncRamDualByteEnable
      generic map
      (
         is_simu     => not use_cyclone5_primitive,
         is_cyclone5 => use_cyclone5_primitive,
         BYTE_WIDTH  => 8,
         ADDR_WIDTH  => 10,
         BYTES       => 4
      )
      port map
      (
         clk       => clk,
         ce_a      => '1',
         addr_a    => to_integer(brom_addr(11 downto 2)),
         datain_a0 => x"00", datain_a1 => x"00", datain_a2 => x"00", datain_a3 => x"00",
         dataout_a => hot_q,
         we_a      => '0',
         be_a      => "0000",
         ce_b      => '1',
         addr_b    => to_integer(load_addr),
         datain_b0 => load_data(7 downto 0),
         datain_b1 => load_data(15 downto 8),
         datain_b2 => load_data(23 downto 16),
         datain_b3 => load_data(31 downto 24),
         dataout_b => open,
         we_b      => load_we,
         be_b      => load_be
      );

      process (clk)
      begin
         if rising_edge(clk) then
            if to_integer(brom_addr) <= t_rom'high then
               hot_valid_q <= '1';
            else
               hot_valid_q <= '0';
            end if;
            if to_integer(brom_addr) <= t_hle'high then
               hle_q <= HLE(to_integer(brom_addr));
            else
               hle_q <= (others => '0');
            end if;
         end if;
      end process;

      brom_data <= hle_q when load_done = '0'
                   else hot_q when hot_valid_q = '1'
                   else x"00000000";
   end generate;

end architecture;
